var a=`0285-prebranac`;var i=`world-0285`;var n=`RS`;var o=`southern-europe`;var r=4;var s=860;var l={en:`Prebranac`,ua:`Пребранац`};var u={en:`A traditional Serbia dish made with cannellini beans, yellow onion, garlic, tomato passata. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Сербія. Основні інгредієнти: квасоля каннеліні, жовта цибуля, часник, томатна пасата. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var g=[{en:`Cover the ingredients with cold water and soak for about 720 minutes; keep fish in the refrigerator, refreshing the water several times to remove excess salt. Drain before cooking.`,ua:`Залийте складники холодною водою і замочуйте приблизно 720 хвилин; рибу тримайте в холодильнику, кілька разів змінюючи воду для видалення зайвої солі. Перед готуванням злийте воду.`,t:[`soaking-legumes`],m:720,i:[[`cannellini-beans`,400,`g`],[`water`,1200,`ml`]]},{en:`Cook the listed ingredients in simmering water for about 85 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 85 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:85,i:[]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 10 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 10 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:10,i:[[`yellow-onion`,280,`g`],[`extra-virgin-olive-oil`,60,`ml`],[`garlic`,4,`clove`],[`sweet-paprika`,9,`g`]]},{en:`Bake in a preheated 180°C oven for about 45 minutes until set, golden and cooked through. Cool on a rack.`,ua:`Випікайте в розігрітій до 180°C духовці приблизно 45 хвилин до рум’яності та повної готовності. Остудіть на решітці.`,t:[`baking`],m:45,i:[[`tomato-passata`,250,`g`],[`bay-leaf`,2,`leaf`],[`table-salt`,null,`to_taste`]]}];var d={slug:a,id:i,country:`RS`,region:o,servings:4,minutes:860,title:l,text:u,steps:g};export{n as country,d as default,i as id,s as minutes,o as region,r as servings,a as slug,g as steps,u as text,l as title};